! Reads columns from a text file, calls the unmodified CUCTRACER, writes the tendencies.
PROGRAM DRIVER
  USE PARKIND1, ONLY : JPIM, JPRB
  USE YOECUMF, ONLY : TECUMF
  USE YOECUMF2, ONLY : TECUMF2
  USE YOMCUMFS, ONLY : TCUMFS
  IMPLICIT NONE
  TYPE(TCUMFS) :: YDCUMFS
  TYPE(TECUMF) :: YDECUMF
  TYPE(TECUMF2) :: YDECUMF2
  INTEGER(KIND=JPIM) :: NCOL, KLEV, KTRAC, JC, JK, JN, ILDCUM, ILDDRAF
  INTEGER(KIND=JPIM) :: KCTOP(1), KDTOP(1), KTYPE(1)
  LOGICAL :: LDCUM(1), LDDRAF(1)
  REAL(KIND=JPRB) :: PTSPHY
  REAL(KIND=JPRB), ALLOCATABLE :: PAPH(:,:), PAP(:,:), PMFU(:,:), PMFD(:,:), PUDRATE(:,:), PDDRATE(:,:), &
   & ZERO(:,:), PCEN(:,:,:), PTENC(:,:,:), PSCAV(:)
  OPEN(10, FILE='columns.txt', STATUS='OLD')
  OPEN(11, FILE='tendencies.txt', STATUS='REPLACE')
  READ(10,*) NCOL
  DO JC = 1, NCOL
    READ(10,*) KLEV, KTRAC, PTSPHY, KCTOP(1), KDTOP(1), ILDCUM, ILDDRAF
    ALLOCATE(PAPH(1,KLEV+1), PAP(1,KLEV), PMFU(1,KLEV), PMFD(1,KLEV), PUDRATE(1,KLEV), PDDRATE(1,KLEV))
    ALLOCATE(ZERO(1,KLEV), PCEN(1,KLEV,KTRAC), PTENC(1,KLEV,KTRAC), PSCAV(KTRAC))
    READ(10,*) (PAPH(1,JK), JK=1,KLEV+1)
    READ(10,*) (PMFU(1,JK), JK=1,KLEV)
    READ(10,*) (PMFD(1,JK), JK=1,KLEV)
    READ(10,*) (PUDRATE(1,JK), JK=1,KLEV)
    READ(10,*) (PDDRATE(1,JK), JK=1,KLEV)
    DO JN = 1, KTRAC
      READ(10,*) (PCEN(1,JK,JN), JK=1,KLEV)
    ENDDO
    DO JK = 1, KLEV
      PAP(1,JK) = 0.5_JPRB*(PAPH(1,JK)+PAPH(1,JK+1))
    ENDDO
    ZERO = 0.0_JPRB; PTENC = 0.0_JPRB; PSCAV = 0.0_JPRB
    KTYPE(1) = 1; LDCUM(1) = ILDCUM == 1; LDDRAF(1) = ILDDRAF == 1
    CALL CUCTRACER(YDCUMFS, YDECUMF2, YDECUMF, 1, 1, 1, KLEV, KTRAC, KCTOP, KDTOP, KTYPE, &
     & LDCUM, LDDRAF, PTSPHY, PAPH, PAP, PMFU, PMFD, PMFU, PMFD, PUDRATE, PDDRATE, ZERO, ZERO, &
     & PCEN, PTENC, PSCAV)
    DO JN = 1, KTRAC
      WRITE(11,'(200ES26.17E3)') (PTENC(1,JK,JN), JK=1,KLEV)
    ENDDO
    DEALLOCATE(PAPH, PAP, PMFU, PMFD, PUDRATE, PDDRATE, ZERO, PCEN, PTENC, PSCAV)
  ENDDO
END PROGRAM DRIVER
